<template>
<main class="bank">
  <template v-if="view==='home'">
    <header class="hero"><small>INTERVIEW QUESTION BANK</small><h1>前端面试题库</h1><p>搜索题目，或按分类开始练习。</p><form class="search" @submit.prevent="openList"><input v-model.trim="keyword" placeholder="搜索面试题" /><button>搜索</button></form></header>
    <section><small>QUICK START</small><h2>快捷入口</h2><div class="quick"><button @click="start(0)"><i>◎</i><b>顺序练习</b></button><button @click="startRandom"><i>↝</i><b>随机练习</b></button><button @click="openList"><i>⌕</i><b>选择题库</b></button></div></section>
    <section><div class="heading"><div><small>CATEGORIES</small><h2>专项练习</h2></div><span>{{categories.length}} 个分类 · {{totalQuestion}} 题</span></div><div class="categories"><button v-for="item in categories" :key="item.id" @click="openCategory(item)"><i>{{item.icon}}</i><span><b>{{item.name}}</b><small>{{item.total}} 题</small></span><em>{{item.exercised?'已练习 '+item.exercised+' 题':'开始练习 ↗'}}</em></button></div></section>
  </template>
  <template v-else-if="view==='list'">
    <header class="hero list-head"><button class="back" @click="goHome">‹ 返回题库首页</button><h1>选择题列表</h1><p>已加载 {{questions.length}} 题，选择或搜索具体题目</p><div class="search"><input v-model.trim="keyword" placeholder="按标题、题干或分类搜索" /><button>搜索</button></div></header>
    <nav class="filters"><button :class="{active:!category}" @click="category=''">全部</button><button v-for="item in availableCategories" :key="item.id" :class="{active:category===item.id}" @click="category=item.id">{{item.name}}</button></nav>
    <section class="list"><button v-for="(q,i) in filtered" :key="q.id" @click="start(i)"><i>{{i+1}}</i><span><b>{{q.title}}</b><small>{{q.type==='multiple'?'多选题':'单选题'}} · {{q.difficulty||'未分级'}} · {{q.categoryName}}</small></span><strong>›</strong></button><p v-if="!filtered.length" class="empty">当前筛选条件下暂无已导入题目。</p></section>
  </template>
  <template v-else>
    <header class="hero practice-head"><button class="back" @click="view='list'">‹ 返回题目列表</button><h1>{{current.title}}</h1><p>{{current.type==='multiple'?'多选题':'单选题'}} · {{current.categoryName}} · {{current.difficulty}}</p></header>
    <article class="card"><p v-if="current.description" class="desc">{{current.description}}</p><div class="options"><button v-for="o in current.options" :key="o.key" :disabled="submitted" :class="optionClass(o.key)" @click="toggle(o.key)"><i>{{o.key}}</i>{{o.text}}</button></div><button v-if="!submitted" class="confirm" :disabled="!selected.length" @click="submitted=true">确认答案</button><section v-else class="result"><div><span><b>正确答案</b> {{current.answer.join('、')}}</span><span :class="isCorrect?'right':'wrong'"><b>你的答案</b> {{selected.join('、')}}</span></div><h2>参考答案与解析</h2><p>{{current.explanation||'该题暂无详细解析。'}}</p></section></article>
    <footer class="pager"><span>答题卡 {{position+1}}/{{filtered.length}}</span><div><button :disabled="position===0" @click="move(-1)">‹ 上一题</button><button :disabled="position===filtered.length-1" @click="move(1)">下一题 ›</button></div></footer>
  </template>
</main>
</template>
<script>
const home=require('../data/question-bank-home'),questions=require('../data/questions.json').questions
export default{name:'QuestionBank',data:()=>({view:'home',categories:home.categories,totalQuestion:home.totalQuestion,questions,keyword:'',category:'',currentId:'',selected:[],submitted:false}),computed:{filtered(){const w=this.keyword.toLowerCase();return this.questions.filter(q=>(!this.category||q.category===this.category)&&(!w||`${q.title} ${q.description} ${q.categoryName}`.toLowerCase().includes(w)))},availableCategories(){const ids=this.questions.map(q=>q.category);return this.categories.filter(c=>ids.includes(c.id))},position(){const i=this.filtered.findIndex(q=>q.id===this.currentId);return i<0?0:i},current(){return this.filtered[this.position]||this.questions[0]},isCorrect(){return [...this.selected].sort().join(',')===[...this.current.answer].sort().join(',')}},methods:{goHome(){this.view='home';this.keyword='';this.category=''},openList(){this.category='';this.view='list'},openCategory(i){this.keyword='';this.category=i.id==='select-question'?'':i.id;this.view='list'},start(i){if(!this.filtered.length)return;this.currentId=this.filtered[i].id;this.selected=[];this.submitted=false;this.view='practice'},startRandom(){this.keyword='';this.category='';this.start(Math.floor(Math.random()*this.questions.length))},toggle(k){this.selected=this.current.type==='single'?[k]:(this.selected.includes(k)?this.selected.filter(v=>v!==k):[...this.selected,k])},optionClass(k){return{selected:this.selected.includes(k),correct:this.submitted&&this.current.answer.includes(k),wrong:this.submitted&&this.selected.includes(k)&&!this.current.answer.includes(k)}},move(n){this.currentId=this.filtered[this.position+n].id;this.selected=[];this.submitted=false}}}
</script>
<style scoped>
.bank{max-width:1180px;margin:auto;padding:1.5rem 1rem 5rem;color:#10233f}.hero{padding:3rem;border-radius:22px;color:#fff;background:linear-gradient(135deg,#172554,#063b4b)}.hero h1{color:#fff}.hero>small,section>small,.heading small{color:#19ae78;letter-spacing:.16em;font-weight:bold}.search{display:flex;max-width:720px;margin:1.5rem auto 0;padding:.35rem;border-radius:28px;background:#fff}.search input{flex:1;min-width:0;padding:.7rem 1rem;border:0;outline:0}.search button,.confirm{padding:.65rem 1.4rem;border:0;border-radius:22px;background:#35b47d;color:#fff}.bank>section{margin-top:3rem}.quick,.categories{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.quick button,.categories button,.list>button{display:flex;align-items:center;gap:1rem;padding:1.2rem;border:1px solid #e2e8f0;border-radius:16px;background:#fff;text-align:left}.quick i,.categories i{display:grid;place-items:center;width:46px;height:46px;border-radius:12px;background:#effaf6;color:#0a9563;font-style:normal}.categories{grid-template-columns:repeat(4,1fr)}.categories button{position:relative;min-height:105px;padding-bottom:2rem}.categories span,.categories small{display:block}.categories small,.categories em{color:#64748b;font-size:.75rem}.categories em{position:absolute;bottom:.6rem;left:1.2rem;font-style:normal}.heading{display:flex;align-items:end;justify-content:space-between}.list-head{text-align:center}.back{display:block;padding:.4rem .8rem;border:1px solid #ffffff50;border-radius:18px;background:#ffffff15;color:#fff}.filters{display:flex;gap:.5rem;overflow:auto;padding:1.5rem 0}.filters button{white-space:nowrap;padding:.45rem .8rem;border:1px solid #ddd;border-radius:18px;background:#fff}.filters .active{background:#e9fbf4;color:#087b51}.list{display:grid;gap:.8rem}.list>button>i{min-width:34px;text-align:center;font-style:normal}.list>button>span{flex:1}.list b,.list small{display:block}.list small{margin-top:.5rem;color:#8491a3}.empty{text-align:center}.practice-head{text-align:center}.practice-head h1{max-width:900px;margin:1.5rem auto;font-size:1.8rem}.card{margin-top:-1rem;padding:2rem;border:1px solid #ddd;border-radius:18px;background:#fff}.desc{padding:1rem;background:#f8fafc}.options{display:grid;gap:.8rem;margin:1.5rem 0}.options button{display:flex;gap:.8rem;padding:1rem;border:1px solid #ddd;border-radius:12px;background:#fff;text-align:left}.options i{color:#098b60;font-style:normal;font-weight:bold}.options .selected{border-color:#35b47d;background:#effcf6}.options .correct{border-color:#10b981;background:#e9fbf4}.options .wrong{border-color:#ef4444;background:#fff0f1}.confirm{display:block;margin:auto}.confirm:disabled{opacity:.4}.result>div{display:grid;grid-template-columns:1fr 1fr;gap:1rem}.result span{padding:1rem;border-radius:10px;background:#e9fbf4;color:#087b51}.result .wrong{background:#fff0f1;color:#dc2638}.pager{display:flex;justify-content:space-between;position:sticky;bottom:0;padding:1rem;border:1px solid #ddd;background:#fff}.pager button{padding:.6rem 1rem;border:0;background:#35b47d;color:#fff}.pager button:disabled{opacity:.4}@media(max-width:760px){.hero{padding:2rem 1.2rem}.quick,.categories{grid-template-columns:1fr 1fr}.result>div{grid-template-columns:1fr}}@media(max-width:450px){.quick,.categories{grid-template-columns:1fr}.heading{display:block}}
</style>
